import sys, random
sys.path.insert(0, ".")
from utils import clamp
def orig(x, lo, hi):
    return max(lo, min(x, hi))
rnd = random.Random(3)
cases = [(5, 0, 3), (-1, 0, 3), (2, 0, 3), (0, 0, 3), (3, 0, 3), (1.5, 1, 2), (5, 3, 0), (-5, 3, 0), (2, 3, 0), (1, 1, 1)]
cases += [(rnd.randint(-50, 50), rnd.randint(-50, 50), rnd.randint(-50, 50)) for _ in range(500)]
cases += [(rnd.uniform(-5, 5), rnd.uniform(-5, 5), rnd.uniform(-5, 5)) for _ in range(200)]
for c in cases:
    r, e = clamp(*c), orig(*c)
    if r != e or type(r) is not type(e):
        sys.exit(1)
if clamp(x=7, lo=0, hi=3) != 3:
    sys.exit(1)
sys.exit(0)
